/* PT LBP OTC Platform - browser-only institutional operations demonstration. */
const APP = (() => {
  const $ = (s) => document.querySelector(s);
  const state = {
    lang: localStorage.getItem('lbp_lang') || 'EN', role: localStorage.getItem('lbp_role') || 'Management / Super Admin',
    view: location.hash === '#portal' ? 'dashboard' : 'landing', module: 'dashboard', period: 'Monthly',
    ledgerSearch: '', ledgerStatus: '', asset: 'ALL', currency: 'IDR', audit: JSON.parse(localStorage.getItem('lbp_desk_audit') || '[]'), modal: null
  };
  const tr = {
    EN: { landing:'Public site', dashboard:'Dashboard', ledger:'Transaction Ledger', fiat:'Fiat Ledger', crypto:'Crypto Ledger', desks:'OTC Desks', clients:'Corporate Clients', aum:'AUM / Treasury', reconciliation:'Reconciliation', reports:'Reports', exports:'Export Center', audit:'Audit Trail', settings:'Settings', period:'Period', asset:'Asset', currency:'Currency', role:'Testing role', search:'Search transaction, client, bank reference or TXID', all:'All', demo:'DEMO DATA - NOT FOR PRODUCTION OR PUBLIC RELIANCE', openPortal:'Open Portal', request:'Request Access', signIn:'Sign In', volume:'OTC Total Volume', fiatIn:'Fiat IN', fiatOut:'Fiat OUT', cryptoIn:'Crypto IN', cryptoOut:'Crypto OUT', revenue:'Net Brokerage Revenue', aumLabel:'Managed Assets AUM', transactions:'Transaction Count', addClient:'Add Client', detail:'Transaction detail', close:'Close', export:'Export', generate:'Generate report', viewDossier:'View dossier', today:'Today', daily:'Daily', weekly:'Weekly', monthly:'Monthly', inception:'Since Inception', custom:'Custom Range' },
    ID: { landing:'Situs publik', dashboard:'Dasbor', ledger:'Buku Transaksi', fiat:'Buku Fiat', crypto:'Buku Kripto', desks:'Meja OTC', clients:'Klien Korporasi', aum:'AUM / Treasury', reconciliation:'Rekonsiliasi', reports:'Laporan', exports:'Pusat Ekspor', audit:'Jejak Audit', settings:'Pengaturan', period:'Periode', asset:'Aset', currency:'Mata uang', role:'Role pengujian', search:'Cari transaksi, klien, referensi bank atau TXID', all:'Semua', demo:'DATA DEMO - BUKAN UNTUK PRODUKSI ATAU RUJUKAN PUBLIK', openPortal:'Buka Portal', request:'Minta Akses', signIn:'Masuk', volume:'Total Volume OTC', fiatIn:'Fiat Masuk', fiatOut:'Fiat Keluar', cryptoIn:'Kripto Masuk', cryptoOut:'Kripto Keluar', revenue:'Pendapatan Broker Bersih', aumLabel:'AUM Terkelola', transactions:'Jumlah Transaksi', addClient:'Tambah Klien', detail:'Detail transaksi', close:'Tutup', export:'Ekspor', generate:'Buat laporan', viewDossier:'Lihat dossier', today:'Hari ini', daily:'Harian', weekly:'Mingguan', monthly:'Bulanan', inception:'Sejak Awal', custom:'Rentang Kustom' }
  };
  const t = (k) => tr[state.lang][k] || k;
  const roles = ['Management / Super Admin','OTC Desk Trader','Finance / Treasury','Compliance / AML','Corporate Client'];
  const roleMenus = {
    'Management / Super Admin':['dashboard','ledger','fiat','crypto','desks','clients','aum','reconciliation','reports','exports','audit','settings'],
    'OTC Desk Trader':['dashboard','ledger','desks'],
    'Finance / Treasury':['dashboard','fiat','crypto','aum','reconciliation','reports','exports'],
    'Compliance / AML':['dashboard','ledger','clients','reconciliation','audit'],
    'Corporate Client':['dashboard','ledger','aum','reports']
  };
  const icons = {dashboard:'◫',ledger:'▤',fiat:'$',crypto:'◈',desks:'▦',clients:'◉',aum:'◌',reconciliation:'↻',reports:'▧',exports:'⇩',audit:'◷',settings:'⚙'};
  const clients = [
    ['C-001','Nusantara Infrastruktur Persada','Corporate','Gold'],['C-002','Garuda Prima Capital','Institutional Fund','Platinum'],['C-003','Meridian Payment Network','Payment Gateway','Gold'],['C-004','Cakrawala Energi Makmur','Corporate','Silver'],['C-005','Arunika Strategic Fund','Institutional Fund','Platinum'],['C-006','Sarana Niaga Digital','Payment Gateway','Gold'],['C-007','Indo Pacific Resources','Corporate','Gold'],['C-008','Sentra Dana Abadi','Institutional Fund','Silver'],['C-009','Karya Integrasi Nusantara','Corporate','Silver'],['C-010','Lintas Data Finansial','Payment Gateway','Gold'],['C-011','Samudra Indo Investama','Institutional Fund','Platinum'],['C-012','Bumi Konektivitas Utama','Corporate','Gold'],['C-013','Prima Setelmen Indonesia','Payment Gateway','Silver'],['C-014','Kencana Asset Mandiri','Institutional Fund','Gold']
  ].map(([id,name,tier,rank]) => ({id,name,tier,rank,kyc:'Verified'}));
  const desks = ['Desk 01','Desk 02','Desk 03','Desk 04','Desk 05'].map((name,i)=>({name,buy:15810-i*7,sell:15855-i*6,spread:.28+i*.03,fee:.20+i*.02}));
  const assets = ['USDT','USDC','BTC','IDR','USD'];
  const banks = ['Bank Mandiri','BCA','BRI']; const rails=['RTGS','BI-FAST','Wire']; const lps=['Garuda Digital Liquidity','Pacific Block Markets','Nusa OTC Liquidity','Archipelago Digital Markets'];
  const hash = (n) => Array.from({length:36},(_,i)=>((n*31+i*17)%16).toString(16)).join('');
  const txs = Array.from({length:220},(_,i)=>{
    const client=clients[(i*7+i)%clients.length], asset=assets[i%assets.length], crypto=['USDT','USDC','BTC'].includes(asset);
    const date=new Date(Date.UTC(2026,3+(i%7),1+(i*11)%27,8+(i%9),10+(i*7)%49));
    const direction=i%3===0?'Crypto → Fiat':i%3===1?'Fiat → Crypto':'Buy / Sell'; const status=['Settled','Settled','Reconciled','Processing','Pending','Exception'][i%6];
    const rate=asset==='BTC'?1035000000:asset==='USDT'?15835+(i%60):asset==='USDC'?15824+(i%48):asset==='USD'?15790+(i%70):1;
    const units=asset==='BTC'?1.2+(i%13)*.37:crypto?65000+(i%90)*12800:680000000+(i%90)*37000000;
    const value=asset==='IDR'?units:units*rate; const fiatIn=direction==='Fiat → Crypto'||(!crypto&&i%2===0); const inAmount=fiatIn?value:units; const outAmount=fiatIn?units:value;
    return {id:`OTC-2026-${String(i+1).padStart(4,'0')}`,date,client,asset,direction,status,rate,units,value,inAmount,outAmount,desk:desks[i%5].name,kyc:i%17?'Verified':'Review',aml:i%19?'Clear':'Alert',bank:banks[i%3],rail:rails[i%3],wallet:`T${hash(i).slice(0,33)}`,txid:hash(i+41)+hash(i+13).slice(0,28),confirmations:12+(i%25),operator:['Treasury Ops','Desk Trader','Settlement Control'][i%3],lp:lps[i%lps.length],spread:.28+(i%5)*.03,fee:.20+(i%4)*.02};
  });
  const format = (n, currency='IDR') => { if(!Number.isFinite(n)) return '—'; if(currency==='IDR') return `Rp ${Math.round(n).toLocaleString('id-ID')}`; if(currency==='USD') return `$${Math.round(n).toLocaleString('en-US')}`; return `${n.toLocaleString('en-US',{maximumFractionDigits:2})}`; };
  const short = (n) => n>=1e12?`Rp ${(n/1e12).toFixed(2)} T`:n>=1e9?`Rp ${(n/1e9).toFixed(1)} B`:format(n);
  const dateText = (date) => date.toLocaleDateString(state.lang==='ID'?'id-ID':'en-GB',{day:'2-digit',month:'short',year:'numeric'});
  const ledgerRows = () => txs.filter(x => {
    const q=state.ledgerSearch.toLowerCase(); const text=[x.id,x.client.name,x.asset,x.bank,x.txid,x.direction].join(' ').toLowerCase();
    return (!q||text.includes(q)) && (!state.ledgerStatus||x.status===state.ledgerStatus) && (state.asset==='ALL'||x.asset===state.asset);
  });
  const pill = (text) => `<span class="pill ${String(text).toLowerCase().replace(' ','')}">${text}</span>`;
  const btn = (label,fn,klass='btn btn-ghost') => `<button class="${klass}" onclick="APP.${fn}">${label}</button>`;
  const table = (rows, type='ledger') => {
    if(!rows.length) return '<div class="empty">No records match the selected criteria.</div>';
    if(type==='ledger') return `<div class="table-wrap"><table class="data-table"><thead><tr><th>TX ID</th><th>Date / Time</th><th>Client</th><th>Order type</th><th>Asset</th><th>IN</th><th>OUT</th><th>Rate</th><th>Desk</th><th>Settlement</th><th>KYC / AML</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="btn btn-ghost data-button mono" onclick="APP.detail('${x.id}')">${x.id}</button></td><td class="mono">${dateText(x.date)}<br>${x.date.toISOString().slice(11,16)} UTC</td><td><b>${x.client.name}</b><br><small>${x.client.id}</small></td><td>${x.direction}</td><td class="mono">${x.asset}</td><td class="mono">${x.asset==='IDR'?format(x.inAmount):format(x.inAmount,'USD')}</td><td class="mono">${x.asset==='IDR'?format(x.outAmount,'USD'):format(x.outAmount)}</td><td class="mono">${x.rate.toLocaleString()}</td><td>${x.desk}</td><td>${pill(x.status)}</td><td>${pill(x.kyc)} ${pill(x.aml)}</td></tr>`).join('')}</tbody></table></div>`;
    return '';
  };
  function landing(){
    return `<div class="landing"><div class="demo-bar">${t('demo')}</div><div class="landing-shell"><nav class="landing-nav"><div class="brand"><i class="brand-mark">L</i><span>PT LINTAS BATAS PEMBAYARAN<small>OTC BROKERAGE & INSTITUTIONAL SETTLEMENT</small></span></div><div class="landing-nav-actions"><button class="language" onclick="APP.language()">${state.lang==='EN'?'ID':'EN'}</button>${btn(t('signIn'),'portal()','btn btn-ghost')}${btn(t('request'),'request()','btn btn-primary')}</div></nav></div><section class="hero"><div class="hero-inner"><span class="eyebrow">OTC BROKERAGE · JAKARTA</span><h1>Institutional OTC Liquidity for Fiat and Digital Assets</h1><p>Controlled demonstration of a unified OTC workflow for rupiah, dollar, stablecoin and digital-asset settlement.</p><div class="hero-actions">${btn(t('openPortal'),'portal()','btn btn-primary')}${btn(t('request'),'request()','btn btn-ghost')}</div><div class="metric-row"><div class="metric-card"><label>SIMULATED VOLUME SINCE INCEPTION</label><strong>Rp 3.54 T</strong></div><div class="metric-card"><label>DEMO INSTITUTIONAL CLIENTS</label><strong>14</strong></div><div class="metric-card"><label>OTC DESKS</label><strong>5</strong></div></div></div></section><section class="landing-section"><div class="landing-shell"><h2 class="section-title">About PT LBP OTC Brokerage</h2><p class="section-copy">The demonstration uses one master ledger to drive operating views for settlement, treasury, reconciliation, reporting and audit. Production deployment requires authenticated access and approved governed data.</p></div></section><section class="landing-section"><div class="landing-shell"><h2 class="section-title">Services</h2><div class="service-grid">${[['⇄','Fiat On Off Ramp','IDR and USD settlement design across RTGS, BI-FAST and wire rails.'],['◈','High Volume Block Trades','Tranche-based execution away from open-market slippage.'],['⌘','Institutional Escrow','Conditional settlement controls and reconciled hand-offs.'],['≈','Deep Liquidity','Execution structure designed around verified institutional capacity.']].map(x=>`<div class="service"><div class="service-icon">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></div></section><section class="landing-section"><div class="landing-shell"><h2 class="section-title">Supported Assets</h2><div class="asset-grid">${[['IDR','Indonesian Rupiah'],['USD','US Dollar'],['USDT','TRC20 / ERC20'],['USDC','ERC20'],['BTC','Bitcoin'],['ETH','Ethereum']].map(x=>`<div class="asset"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}</div></div></section><section class="landing-section"><div class="landing-shell"><div class="landing-cta"><div><h2>Corporate Onboarding</h2><p>Submit an indicative access request for an onboarding discussion.</p></div>${btn(t('request'),'request()','btn btn-blue')}</div><footer class="landing-footer"><span>© 2026 PT Lintas Batas Pembayaran · Demo interface</span><button class="btn btn-ghost" onclick="APP.portal()">${t('openPortal')}</button></footer></div></section></div>`;
  }
  function portal(){
    const menu=roleMenus[state.role].map(key=>`<button class="nav-item ${state.module===key?'active':''}" onclick="APP.go('${key}')"><i>${icons[key]}</i><span>${t(key)}</span></button>`).join('');
    return `<div class="demo-bar">${t('demo')} · Role selector is for interface testing only.</div><div class="portal"><aside class="sidebar"><div class="side-brand"><i class="brand-mark">L</i><span><b>PT LBP</b><br><small>OTC OPERATIONS</small></span></div><div class="nav-caption">OPERATIONS</div><nav>${menu}</nav><div class="sidebar-bottom"><button class="nav-item" onclick="APP.home()"><i>↗</i><span>${t('landing')}</span></button></div></aside><main class="main"><header class="portal-head"><div class="crumb">Portal / <b>${t(state.module)}</b></div><div class="head-actions"><button class="language" onclick="APP.language()">${state.lang==='EN'?'ID':'EN'}</button><select class="role-select" title="Testing role only" onchange="APP.role(this.value)">${roles.map(x=>`<option ${x===state.role?'selected':''}>${x}</option>`).join('')}</select><div class="profile">LBP</div></div></header><section class="content">${view()}</section></main></div>${state.modal||''}`;
  }
  const kpi=(label,value,sub='ledger derived')=>`<div class="kpi"><label>${label}</label><strong>${value}</strong><span>${sub}</span></div>`;
  function view(){return ({dashboard,ledger,fiat,crypto,desks:desksView,clients:clientsView,aum:aumView,reconciliation,reports,exports:exportsView,audit:auditView,settings})[state.module]();}
  function pageHead(title,description,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div>${actions}</div>`;}
  function dashboard(){
    const rows=ledgerRows(), vol=rows.reduce((s,x)=>s+x.value,0), settled=rows.filter(x=>['Settled','Reconciled'].includes(x.status)).length;
    return `${pageHead('OTC Management Dashboard','Synthetic institutional operating view generated from one master ledger.',`<div class="filters"><div class="periods">${[['Today','today'],['Daily','daily'],['Weekly','weekly'],['Monthly','monthly'],['Since Inception','inception']].map(([v,k])=>`<button class="${state.period===v?'active':''}" onclick="APP.period('${v}')">${t(k)}</button>`).join('')}</div><select class="chip" onchange="APP.currency(this.value)"><option>IDR</option><option>USD</option></select><select class="chip" onchange="APP.asset(this.value)">${['ALL','USDT','USDC','BTC','IDR','USD'].map(x=>`<option ${x===state.asset?'selected':''}>${x}</option>`).join('')}</select></div>`)}<div class="notice">Simulation only. Figures are generated in-browser and must not be used as financial, settlement or liquidity evidence.</div><div class="kpi-grid">${kpi(t('volume'),short(vol))}${kpi(t('fiatIn'),short(vol*.51))}${kpi(t('fiatOut'),short(vol*.47))}${kpi(t('cryptoIn'),'$'+Math.round(vol*.000028).toLocaleString())}${kpi(t('cryptoOut'),'$'+Math.round(vol*.000026).toLocaleString())}${kpi(t('revenue'),short(vol*.0026))}${kpi(t('aumLabel'),short(vol*.083))}${kpi(t('transactions'),rows.length,String(settled)+' settled / reconciled')}</div><div class="grid-two"><div class="card"><div class="card-title">Bidirectional settlement flow <span class="chip">${state.period}</span></div><div class="flow"><div class="flow-node"><label>BANK IN / FIAT IN</label><strong>${short(vol*.51)}</strong></div><div class="flow-arrow">→</div><div class="flow-node core"><label>LBP TREASURY CORE</label><strong>${short(vol*.083)}</strong></div><div class="flow-arrow">→</div><div class="flow-node"><label>CRYPTO OUT</label><strong>$${Math.round(vol*.000026).toLocaleString()}</strong></div></div><div class="flow"><div class="flow-node"><label>CRYPTO IN</label><strong>$${Math.round(vol*.000028).toLocaleString()}</strong></div><div class="flow-arrow">→</div><div class="flow-node core"><label>CONTROLLED SETTLEMENT</label><strong>5 DESKS</strong></div><div class="flow-arrow">→</div><div class="flow-node"><label>BANK OUT / FIAT OUT</label><strong>${short(vol*.47)}</strong></div></div></div><div class="card"><div class="card-title">Desk allocation <span class="chip">${rows.length} records</span></div><div class="bars">${desks.map((d,i)=>`<div class="bar-row"><span>${d.name}</span><div class="bar-track"><i style="width:${82-i*9}%"></i></div><b>${short(vol*(.24-i*.018))}</b></div>`).join('')}</div></div></div><div class="card" style="margin-top:15px"><div class="card-title">Recent activity ${btn('Open ledger',"go('ledger')")}</div>${table(rows.slice(0,8))}</div>`;
  }
  function ledger(){const rows=ledgerRows(); return `${pageHead('Master Transaction Ledger',`${rows.length} filterable synthetic transactions in the demonstration ledger.`,btn('+ New demo transaction','newTx()','btn btn-primary'))}<div class="card"><div class="tool-row"><div class="tool-left"><input class="search" value="${state.ledgerSearch}" placeholder="${t('search')}" oninput="APP.search(this.value)"><select class="chip" onchange="APP.status(this.value)"><option value="">${t('all')} statuses</option>${['Settled','Pending','Processing','Reconciled','Exception'].map(x=>`<option ${x===state.ledgerStatus?'selected':''}>${x}</option>`).join('')}</select><select class="chip" onchange="APP.asset(this.value)">${['ALL','USDT','USDC','BTC','IDR','USD'].map(x=>`<option ${x===state.asset?'selected':''}>${x}</option>`).join('')}</select></div>${btn('Export CSV','csv()','btn btn-primary')}</div>${table(rows)}</div>`;}
  function fiat(){const rows=txs.filter(x=>x.asset==='IDR'||x.asset==='USD');return `${pageHead('Fiat Ledger','Simulated bank settlements across Mandiri, BCA and BRI.',btn('Export CSV','csv()'))}<div class="card">${table(rows)}</div>`;}
  function crypto(){const rows=txs.filter(x=>['USDT','USDC','BTC'].includes(x.asset));return `${pageHead('Crypto Ledger','Synthetic on-chain deposits, withdrawals and confirmation status.',btn('Export CSV','csv()'))}<div class="card"><div class="notice">Wallet addresses and transaction hashes are demonstration-only values.</div>${table(rows)}</div>`;}
  function desksView(){const rows=['Buy Price','Sell Price','Spread %','Fee %','Client Price','Gross Spread','Desk Revenue','Broker Revenue','Net Margin']; const values=(d,row)=>{const x={"Buy Price":d.buy,"Sell Price":d.sell,"Spread %":d.spread.toFixed(2)+'%',"Fee %":d.fee.toFixed(2)+'%',"Client Price":Math.round(d.sell*(1+d.fee/100)).toLocaleString(),"Gross Spread":'$ '+Math.round((d.sell-d.buy)*140000).toLocaleString(),"Desk Revenue":'$ '+Math.round((d.sell-d.buy)*78000).toLocaleString(),"Broker Revenue":'$ '+Math.round(d.sell*60000*d.fee/100).toLocaleString(),"Net Margin":(d.spread-d.fee).toFixed(2)+'%'};return x[row]};return `${pageHead('OTC Desks 01 to 05','Editable demonstration matrix. Each saved change creates a browser-local audit event.',`${btn('View edit audit','deskAudit()','btn btn-ghost')} ${btn('Edit desk','editDesk(0)','btn btn-primary')}`)}<div class="card"><div class="table-wrap"><div class="desk-matrix"><div class="head">Configuration</div>${desks.map(d=>`<div class="head">${d.name}</div>`).join('')}${rows.map(row=>`<div class="label">${row}</div>${desks.map((d,i)=>`<div class="metric">${values(d,row)}${row==='Buy Price'||row==='Sell Price'?` <button class="btn btn-ghost data-button" onclick="APP.editDesk(${i})">Edit</button>`:''}</div>`).join('')}`).join('')}</div></div></div>`;}
  function clientsView(){return `${pageHead('B2B and Corporate Clients','Institutional directory with synthetic profile, volume and KYC status.',btn('+ '+t('addClient'),'addClient()','btn btn-primary'))}<div class="client-grid">${clients.map((c,i)=>`<div class="client-card"><div style="display:flex;justify-content:space-between;gap:8px"><div><h3>${c.name}</h3><p>${c.id} · ${c.tier} · ${c.rank}</p></div>${pill(c.kyc)}</div><div class="client-stats"><span>Volume<br><b>${short((8+i*2.3)*1e9)}</b></span><span>Net flow<br><b>${short((.7+i*.18)*1e9)}</b></span><span>AUM<br><b>${short((.5+i*.11)*1e9)}</b></span></div><div style="margin-top:14px">${btn(t('viewDossier'),`dossier('${c.id}')`)}</div></div>`).join('')}</div>`;}
  function aumView(){return `${pageHead('AUM and Treasury','Illustrative reserve allocation and IDR-equivalent calculations.',btn('Configure equivalents','settingsGo()'))}<div class="kpi-grid">${kpi('Opening AUM','Rp 285.4 B','opening position')}${kpi('Current AUM','Rp 312.8 B','current position')}${kpi('Net Inflow','Rp 42.7 B','this period')}${kpi('Net Outflow','Rp 15.3 B','this period')}</div><div class="grid-two"><div class="card"><div class="card-title">Multi-asset reserve breakdown</div><div class="bars">${[['IDR',38,'Rp 118.9 B'],['USD',16,'Rp 50.1 B'],['USDT',29,'Rp 90.7 B'],['USDC',9,'Rp 28.2 B'],['BTC',8,'Rp 24.9 B']].map(x=>`<div class="bar-row"><span>${x[0]}</span><div class="bar-track"><i style="width:${x[1]}%"></i></div><b>${x[2]}</b></div>`).join('')}</div></div><div class="card"><div class="card-title">Treasury control posture</div><p>Segregated settlement structures, wallet screening, dual approval and controlled counterparty execution are represented in this demonstration workflow.</p><div class="notice">Production reserve, bank and wallet values must be supplied from approved governed sources.</div></div></div>`;}
  function reconciliation(){const rows=txs.slice(0,25);return `${pageHead('Automated Reconciliation','Expected versus actual demonstration balances with exception workflow.',btn('+ Log exception','exception()','btn btn-primary'))}<div class="kpi-grid">${kpi('Bank reconciliation','98.7%','expected vs actual')}${kpi('Wallet reconciliation','99.1%','on-chain simulated')}${kpi('Open exceptions','03','investigation required')}${kpi('Pending reversals','02','approval required')}</div><div class="card" style="margin-top:15px"><div class="card-title">Exception and reconciliation queue</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Ledger expected</th><th>Actual</th><th>Rail / chain</th><th>Status</th><th>Workflow</th></tr></thead><tbody>${rows.map((x,i)=>{const ex=i%9===0;return `<tr><td class="mono">${x.id}</td><td>${short(x.value)}</td><td>${short(ex?x.value*.993:x.value)}</td><td>${i%2?'TRC20':'RTGS'}</td><td>${pill(ex?'Exception':'Reconciled')}</td><td>${ex?btn('Investigate',`investigate('${x.id}')`):'—'}</td></tr>`}).join('')}</tbody></table></div></div>`;}
  function reports(){return `${pageHead('Reports','Generate ledger-derived demonstration summaries by reporting period.')}<div class="service-grid">${[['Daily','Daily operations','Settlement, flow, exceptions and revenue.'],['Weekly','Weekly desk review','Desk and client aggregation.'],['Monthly','Monthly management','Executive performance and control overview.'],['Since Inception','Since inception','Cumulative ledger and AUM summary.']].map(x=>`<div class="service"><div class="service-icon">▧</div><h3>${x[1]}</h3><p>${x[2]}</p><div style="margin-top:18px">${btn(t('generate'),`report('${x[0]}')`,'btn btn-primary')}</div></div>`).join('')}</div>`;}
  function exportsView(){return `${pageHead('Export Center','Create browser-side CSV and structured multi-sheet XLSX files from synthetic ledger data.')}<div class="card"><div class="form-grid"><label>Report type<select id="exportType"><option>Transaction ledger</option><option>Reconciliation</option><option>Client statement</option></select></label><label>Date range<select id="exportRange"><option>Since inception</option><option>This month</option><option>Custom range</option></select></label><label>Client<select id="exportClient"><option>All clients</option>${clients.map(c=>`<option>${c.name}</option>`).join('')}</select></label><label>Desk<select id="exportDesk"><option>All desks</option>${desks.map(d=>`<option>${d.name}</option>`).join('')}</select></label><label>Asset<select id="exportAsset"><option>All assets</option>${assets.map(a=>`<option>${a}</option>`).join('')}</select></label><label>Currency<select><option>IDR</option><option>USD</option></select></label></div><div class="modal-actions"><button class="btn btn-primary" onclick="APP.csv()">Export CSV</button><button class="btn btn-blue" onclick="APP.xlsx()">Export XLSX 18 Sheets</button><button class="btn btn-ghost" onclick="APP.pdf()">Printable PDF View</button></div></div>`;}
  function auditView(){const base=Array.from({length:30},(_,i)=>({ts:`2026-10-${String(21-i%7).padStart(2,'0')} ${String(9+i%8).padStart(2,'0')}:${String(12+i).padStart(2,'0')}`,user:['Treasury Ops','Desk 03 Trader','Compliance Team'][i%3],action:['Approved tranche','Reconciled bank reference','Updated settlement status'][i%3],target:txs[i].id,old:i%2?'Processing':'—',next:['Settled','Approved','Reconciled'][i%3]})).concat(state.audit);return `${pageHead('Audit Trail','Append-only demonstration history. Production requires server-side immutable audit evidence.')}<div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Timestamp</th><th>User / Operator</th><th>Action</th><th>Target entity</th><th>Old value</th><th>New value</th></tr></thead><tbody>${base.map(x=>`<tr><td class="mono">${x.ts}</td><td>${x.user}</td><td>${x.action}</td><td class="mono">${x.target}</td><td>${x.old}</td><td>${x.next}</td></tr>`).join('')}</tbody></table></div></div>`;}
  function settings(){return `${pageHead('Settings','Demonstration defaults stored in the current browser only.',btn('Save browser settings','saveSettings()','btn btn-primary'))}<div class="grid-two"><div class="card"><div class="card-title">Reference exchange rates</div><div class="form-grid"><label>USD / IDR<input value="15,820"></label><label>USDT / IDR<input value="15,842"></label><label>USDC / USD<input value="1.0001"></label></div></div><div class="card"><div class="card-title">Desk defaults</div><p>Default fee: 0.20%<br>Default spread target: 0.28%<br>Transaction approval: dual control<br>Default language: ${state.lang}</p></div></div>`;}
  function modal(title,body,subtitle=''){state.modal=`<div class="modal-backdrop" onclick="APP.close(event)"><div class="modal" onclick="event.stopPropagation()"><div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="close" onclick="APP.close()">×</button></div>${body}</div></div>`;render();}
  function render(){document.getElementById('app').innerHTML=state.view==='landing'?landing():portal();}
  return {
    portal(){state.view='portal';location.hash='portal';render()},home(){state.view='landing';history.replaceState(null,'',location.pathname);render()},language(){state.lang=state.lang==='EN'?'ID':'EN';localStorage.setItem('lbp_lang',state.lang);render()},role(v){state.role=v;localStorage.setItem('lbp_role',v);if(!roleMenus[v].includes(state.module))state.module='dashboard';render()},go(m){state.module=m;render()},period(v){state.period=v;render()},asset(v){state.asset=v;render()},currency(v){state.currency=v;render()},search(v){state.ledgerSearch=v;render()},status(v){state.ledgerStatus=v;render()},close(e){if(!e||e.target===e.currentTarget){state.modal=null;render()}},
    request(){modal('Request Corporate Access','<div class="notice">This form is a non-submitting demonstration. Do not enter confidential, banking or wallet information.</div><div class="form-grid"><label>Entity name<input placeholder="Corporate entity"></label><label>Contact email<input placeholder="name@company.com"></label><label>Indicative requirement<select><option>OTC execution discussion</option><option>Settlement design</option><option>Institutional onboarding</option></select></label></div><div class="modal-actions">'+btn(t('close'),'close()')+'<button class="btn btn-primary" onclick="APP.submitDemo()">Submit demonstration request</button></div>','Indicative access request')},
    submitDemo(){modal('Request recorded','<p>Your demonstration request was recorded only in this browser session. No data has been transmitted.</p><div class="modal-actions">'+btn(t('close'),'close()')+'</div>','Demo confirmation')},
    detail(id){const x=txs.find(a=>a.id===id); modal(`${t('detail')} · ${x.id}`,`<p>${pill(x.status)} ${pill(x.kyc)} ${pill(x.aml)}</p><div class="detail-grid">${[['Client',x.client.name],['Counterparty',x.client.name],['Liquidity Provider',x.lp],['Desk',x.desk],['Order type',x.direction],['Asset',x.asset],['Broker spread',x.spread.toFixed(2)+'%'],['Fee',x.fee.toFixed(2)+'%'],['Bank reference',x.bank+' · '+x.rail],['Blockchain TXID',x.txid],['Confirmations',x.confirmations],['Operator',x.operator],['Institutional settlement address',x.wallet],['Exchange rate',x.rate.toLocaleString()]].map(x=>`<div class="detail"><label>${x[0]}</label><span class="mono">${x[1]}</span></div>`).join('')}</div><div class="modal-actions">${btn('View explorer','explorer()')}<button class="btn btn-primary" onclick="APP.voucher('${x.id}')">Download voucher</button></div>`,'Synthetic transaction detail')},
    explorer(){alert('Demonstration only: explorer links are disabled for synthetic transaction hashes.')},voucher(id){const x=txs.find(a=>a.id===id);const text=`PT LBP OTC DEMONSTRATION VOUCHER\nTransaction: ${x.id}\nClient: ${x.client.name}\nAsset: ${x.asset}\nStatus: ${x.status}\nGenerated: ${new Date().toISOString()}\n\nThis is synthetic demonstration data only.`; download(text,`voucher-${id}.txt`,'text/plain');},
    editDesk(i){const d=desks[i];modal(`Edit ${d.name}`,`<div class="notice">Testing-only configuration. Saving creates a browser-local audit record; it does not alter any production price.</div><div class="form-grid"><label>Buy price<input id="deskBuy" value="${d.buy}"></label><label>Sell price<input id="deskSell" value="${d.sell}"></label><label>Spread percent<input id="deskSpread" value="${d.spread}"></label><label>Fee percent<input id="deskFee" value="${d.fee}"></label></div><div class="modal-actions">${btn(t('close'),'close()')}<button class="btn btn-primary" onclick="APP.saveDesk(${i})">Save and log change</button></div>`,'Controlled demo edit')},
    saveDesk(i){const d=desks[i], old=`Buy ${d.buy} · Sell ${d.sell} · Spread ${d.spread}% · Fee ${d.fee}%`;d.buy=Number($('#deskBuy').value)||d.buy;d.sell=Number($('#deskSell').value)||d.sell;d.spread=Number($('#deskSpread').value)||d.spread;d.fee=Number($('#deskFee').value)||d.fee;state.audit.unshift({ts:new Date().toISOString().slice(0,16).replace('T',' '),user:state.role,action:'Updated desk configuration',target:d.name,old,next:`Buy ${d.buy} · Sell ${d.sell} · Spread ${d.spread}% · Fee ${d.fee}%`});localStorage.setItem('lbp_desk_audit',JSON.stringify(state.audit));state.modal=null;render()},
    deskAudit(){state.module='audit';render()},addClient(){modal('Add Corporate Client','<div class="notice">Demonstration form only. Client records are not persisted or transmitted.</div><div class="form-grid"><label>Entity name<input placeholder="Legal entity name"></label><label>Client tier<select><option>Corporate</option><option>Institutional Fund</option><option>Payment Gateway</option></select></label><label>KYC state<select><option>Pending review</option><option>Verified</option></select></label></div><div class="modal-actions">'+btn(t('close'),'close()')+'</div>')},
    dossier(id){const c=clients.find(x=>x.id===id);modal(`Client dossier · ${c.id}`,`<div class="detail-grid">${[['Entity',c.name],['Tier',c.tier],['Rank',c.rank],['KYC status',c.kyc],['Transactions',Math.round(12+clients.indexOf(c)*7)],['Data classification','Synthetic demo record']].map(x=>`<div class="detail"><label>${x[0]}</label><span>${x[1]}</span></div>`).join('')}</div><div class="modal-actions">${btn(t('close'),'close()')}</div>`,'Demo client record')},
    exception(){modal('Log Exception','<div class="notice">Demonstration workflow only. No incident is created outside this browser.</div><div class="form-grid"><label>Reference<input placeholder="OTC-2026-0001"></label><label>Exception type<select><option>Bank difference</option><option>Wallet difference</option><option>Compliance hold</option></select></label><label>Investigation owner<input placeholder="Operations team"></label></div><div class="modal-actions">'+btn(t('close'),'close()')+'</div>')},investigate(id){modal(`Investigate ${id}`,`<p>Controlled investigation and approval workflow would be performed by authorised users in production.</p><div class="modal-actions">${btn(t('close'),'close()')}</div>`,'Demonstration exception workflow')},
    report(range){modal(`${range} Report`,`<p>Generated from ${txs.length} synthetic ledger entries. In production this view must be generated from governed data and authorised reporting services.</p><div class="kpi-grid">${kpi('Volume',short(txs.reduce((s,x)=>s+x.value,0)))}${kpi('Settled',txs.filter(x=>x.status==='Settled').length)}${kpi('Exceptions',txs.filter(x=>x.status==='Exception').length)}${kpi('Clients',clients.length)}</div><div class="modal-actions"><button class="btn btn-primary" onclick="APP.xlsx()">Export XLSX</button>${btn(t('close'),'close()')}</div>`,'Synthetic reporting summary')},
    csv(){const rows=ledgerRows();const csv=['TX ID,Date Time,Client,Order Type,Asset,IN,OUT,Rate,Desk,Settlement,KYC,AML,Bank,TXID',...rows.map(x=>[x.id,x.date.toISOString(),x.client.name,x.direction,x.asset,x.inAmount,x.outAmount,x.rate,x.desk,x.status,x.kyc,x.aml,x.bank,x.txid].map(v=>`"${String(v).replaceAll('"','""')}"`).join(','))].join('\n');download(csv,'lbp-otc-ledger-demo.csv','text/csv;charset=utf-8')},
    xlsx(){if(!window.XLSX){alert('Spreadsheet library is loading. Please retry in a moment.');return}const wb=XLSX.utils.book_new();const records=txs.map(x=>({'TX ID':x.id,'Date Time':x.date.toISOString(),Client:x.client.name,'Order Type':x.direction,Asset:x.asset,IN:x.inAmount,OUT:x.outAmount,Rate:x.rate,Desk:x.desk,Settlement:x.status,KYC:x.kyc,AML:x.aml,Bank:x.bank,TXID:x.txid}));const summary=[['PT LBP OTC PLATFORM','SYNTHETIC DEMONSTRATION REPORT'],['Generated',new Date().toISOString()],['Record count',records.length],['Important','Not for operational, financial or settlement reliance']];const sheets=[['01 Executive Summary',summary],['02 Transaction Ledger',records],['03 Fiat Flow',records.filter(x=>x.Asset==='IDR'||x.Asset==='USD')],['04 Crypto Flow',records.filter(x=>['USDT','USDC','BTC'].includes(x.Asset))],['05 OTC Brokerage',records],...desks.map((d,i)=>[`0${6+i} ${d.name}`,records.filter(x=>x.Desk===d.name)]),['11 B2B Corporate Clients',clients],['12 Daily Summary',records],['13 Weekly Summary',records],['14 Monthly Summary',records],['15 AUM',[['Asset','IDR Equivalent'],['IDR',118900000000],['USD',50100000000],['USDT',90700000000],['USDC',28200000000],['BTC',24900000000]]],['16 Reconciliation',records.map(x=>({'TX ID':x['TX ID'],Status:x.Settlement,'Expected':x.IN,'Actual':x.IN}))],['17 KYC AML Summary',records.map(x=>({Client:x.Client,KYC:x.KYC,AML:x.AML}))],['18 Audit Trail',state.audit]];sheets.forEach(([name,data])=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(Array.isArray(data)&&Array.isArray(data[0])?data.map(r=>Object.fromEntries(r.map((v,i)=>['Column '+(i+1),v]))):data),name.slice(0,31)));XLSX.writeFile(wb,'lbp-otc-demo-report.xlsx')},
    pdf(){window.print()},newTx(){modal('New Demonstration Transaction','<div class="notice">Transaction creation is disabled in this static demo. Production workflow requires authenticated approvals and governed ledger persistence.</div><div class="modal-actions">'+btn(t('close'),'close()')+'</div>')},settingsGo(){state.module='settings';render()},saveSettings(){alert('Demonstration settings saved in this browser only.')}
  };
  function download(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
})();
window.APP=APP;APP.home();
